:[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://coloradoinsuranceappraiser.com/#website","url":"https://coloradoinsuranceappraiser.com/","name":"Colorado Insurance Appraiser","publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#webpage","url":"https://coloradoinsuranceappraiser.com/resources/glossary/","name":"Insurance Claim Glossary | Holdback, ACV, Umpire","description":"Searchable glossary of property insurance claim terms: ACV, RCV, recoverable depreciation, holdback, appraisal award, umpire, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://coloradoinsuranceappraiser.com/#website"},"about":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","breadcrumb":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#breadcrumb"},"primaryImageOfPage":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#primaryimage"},"image":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#primaryimage"},"mainEntity":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://coloradoinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Resources","item":"https://coloradoinsuranceappraiser.com/resources/"},{"@type":"ListItem","position":3,"name":"Glossary","item":"https://coloradoinsuranceappraiser.com/resources/glossary/"}],"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#breadcrumb"},{"@type":"ImageObject","@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#primaryimage","url":"https://coloradoinsuranceappraiser.com/assets/img/photos/calc2.webp","contentUrl":"https://coloradoinsuranceappraiser.com/assets/img/photos/calc2.webp","width":1200,"height":800,"caption":"Calculator on printed financial charts next to a laptop"},{"@type":"DefinedTermSet","name":"Property insurance claim glossary","url":"https://coloradoinsuranceappraiser.com/resources/glossary/","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs are completed.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for the extra cost of living elsewhere while your home is repaired after a covered loss.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Bad faith","description":"An insurer’s unreasonable conduct in handling a claim. A legal issue outside the appraisal process.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Class 4 shingle","description":"A shingle that earned the highest rating in a standard laboratory impact test. Not hail-proof.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Code upgrade","description":"Work required by current building codes when repairing damage, such as ice barrier or ventilation improvements.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy condition that can reduce a payment if property is insured below a required percentage of its value.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Contents","description":"Personal property such as furniture, clothing and electronics, usually Coverage C on a homeowners policy.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"An endorsement that excludes damage affecting appearance but not function, often for metal roofs and siding.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage — the limit for the house itself. Percentage deductibles are calculated from it.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page listing your coverages, limits, deductibles and endorsements.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the insurer pays. May be a flat amount or a percentage.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition. Recoverable depreciation can be paid after repairs.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Downslope windstorm","description":"Strong winds that accelerate down the lee side of the mountains, a frequent cause of Front Range wind damage.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Fair rental value","description":"Coverage for rent you lose when a rental property can’t be occupied after a covered loss.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A last-resort insurance pool for owners who can’t get coverage in the standard market.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Functional damage","description":"Damage that impairs a material’s ability to perform, such as a fractured shingle mat.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation an insurer holds until repairs are completed and documented.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under roofing and into the home.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Impartial appraiser","description":"An appraiser without a financial stake or bias in the outcome, as many policies require.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as “remove and replace laminated shingles, per square.”","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Making repaired areas reasonably uniform in color, texture and appearance with undamaged areas.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping or drying.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to comply with building codes and ordinances during repair or rebuilding.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Other structures","description":"Coverage for detached structures like garages, sheds and fences, usually Coverage B.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for coordinating a multi-trade repair, often around 10% each.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of Coverage A rather than a flat amount.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which an insurer may request within a set time.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the policy will pay once repairs or replacement are completed.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without depreciation.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Roof payment schedule","description":"An endorsement that pays roof losses based on roof age, often reducing payment significantly.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full list of damaged items and the repairs needed — the foundation of any estimate.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Soft metals","description":"Gutters, vents, flashing and similar metal components whose dents help show hail size and direction.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"Extra labor cost added for working on steeper roofs, typically 7/12 pitch and above.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy’s time limit for filing a lawsuit against the insurer.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an estimate after the initial inspection.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Test square","description":"A marked 10-by-10-foot roof area used to count hail hits on a slope.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who decides items the two appraisers can’t resolve.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Waste factor","description":"Extra material added to cover cutting and fitting, higher on complex roofs.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Wildland-urban interface","description":"Areas where homes meet or mix with undeveloped wildland vegetation, with elevated wildfire risk.","inDefinedTermSet":{"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}}],"@id":"https://coloradoinsuranceappraiser.com/resources/glossary/#definedtermset"}]}</script>
</head>
